class Quote {
  const Quote({required this.quoteToken, required this.expiresAt, required this.expiresIn, required this.distanceKm, required this.breakdown, required this.itemsTotal, required this.deliveryFee, required this.discount, required this.total, required this.paymentMethod, required this.configVersion});

  final String quoteToken;
  final DateTime expiresAt;
  final int expiresIn;
  final double distanceKm;
  final List<PriceLine> breakdown;
  final Money itemsTotal;
  final Money deliveryFee;
  final Money discount;
  final Money total;
  final String paymentMethod;
  final int configVersion;

  factory Quote.fromJson(Map<String, dynamic> json) => Quote(
        quoteToken: json['quote_token'] as String,
        expiresAt: DateTime.parse(json['expires_at'] as String),
        expiresIn: (json['expires_in'] as num).toInt(),
        distanceKm: (json['distance_km'] as num).toDouble(),
        breakdown: (json['breakdown'] as List<dynamic>).map((e) => PriceLine.fromJson(Map<String, dynamic>.from(e as Map))).toList(),
        itemsTotal: Money.fromJson(Map<String, dynamic>.from(json['items_total'] as Map)),
        deliveryFee: Money.fromJson(Map<String, dynamic>.from(json['delivery_fee'] as Map)),
        discount: Money.fromJson(Map<String, dynamic>.from(json['discount'] as Map)),
        total: Money.fromJson(Map<String, dynamic>.from(json['total'] as Map)),
        paymentMethod: json['payment_method'] as String,
        configVersion: (json['config_version'] as num).toInt(),
      );

  Map<String, dynamic> toJson() => {
        'quote_token': quoteToken,
        'expires_at': expiresAt.toIso8601String(),
        'expires_in': expiresIn,
        'distance_km': distanceKm,
        'breakdown': breakdown.map((e) => e.toJson()).toList(),
        'items_total': itemsTotal.toJson(),
        'delivery_fee': deliveryFee.toJson(),
        'discount': discount.toJson(),
        'total': total.toJson(),
        'payment_method': paymentMethod,
        'config_version': configVersion,
      };
}

