class Receipt {
  const Receipt({required this.code, required this.project, required this.status, required this.createdAt, this.completedAt, this.driver, required this.payment, required this.items, required this.lines, required this.total});

  final String code;
  final ReceiptProject project;
  final ReceiptStatus status;
  final DateTime createdAt;
  final DateTime? completedAt;
  final String? driver;
  final ReceiptPayment payment;
  final List<ReceiptItem> items;
  final List<ReceiptLine> lines;
  final Money total;

  factory Receipt.fromJson(Map<String, dynamic> json) => Receipt(
        code: json['code'] as String,
        project: ReceiptProject.fromJson(Map<String, dynamic>.from(json['project'] as Map)),
        status: ReceiptStatus.fromJson(Map<String, dynamic>.from(json['status'] as Map)),
        createdAt: DateTime.parse(json['created_at'] as String),
        completedAt: json['completed_at'] == null ? null : DateTime.parse(json['completed_at'] as String),
        driver: json['driver'] as String?,
        payment: ReceiptPayment.fromJson(Map<String, dynamic>.from(json['payment'] as Map)),
        items: (json['items'] as List<dynamic>).map((e) => ReceiptItem.fromJson(Map<String, dynamic>.from(e as Map))).toList(),
        lines: (json['lines'] as List<dynamic>).map((e) => ReceiptLine.fromJson(Map<String, dynamic>.from(e as Map))).toList(),
        total: Money.fromJson(Map<String, dynamic>.from(json['total'] as Map)),
      );

  Map<String, dynamic> toJson() => {
        'code': code,
        'project': project.toJson(),
        'status': status.toJson(),
        'created_at': createdAt.toIso8601String(),
        'completed_at': completedAt?.toIso8601String(),
        'driver': driver,
        'payment': payment.toJson(),
        'items': items.map((e) => e.toJson()).toList(),
        'lines': lines.map((e) => e.toJson()).toList(),
        'total': total.toJson(),
      };
}

