class Tracking {
  const Tracking({required this.orderId, required this.status, this.driver, required this.pickup, required this.dropoff, this.etaMinutes, required this.pathTail, required this.nextPollSeconds});

  final int orderId;
  final Status status;
  final TrackingDriver? driver;
  final GeoPoint pickup;
  final GeoPoint dropoff;
  final int? etaMinutes;
  final List<TrackingPathTail> pathTail;
  final int nextPollSeconds;

  factory Tracking.fromJson(Map<String, dynamic> json) => Tracking(
        orderId: (json['order_id'] as num).toInt(),
        status: Status.fromJson(Map<String, dynamic>.from(json['status'] as Map)),
        driver: json['driver'] == null ? null : TrackingDriver.fromJson(Map<String, dynamic>.from(json['driver'] as Map)),
        pickup: GeoPoint.fromJson(Map<String, dynamic>.from(json['pickup'] as Map)),
        dropoff: GeoPoint.fromJson(Map<String, dynamic>.from(json['dropoff'] as Map)),
        etaMinutes: (json['eta_minutes'] as num?)?.toInt(),
        pathTail: (json['path_tail'] as List<dynamic>).map((e) => TrackingPathTail.fromJson(Map<String, dynamic>.from(e as Map))).toList(),
        nextPollSeconds: (json['next_poll_seconds'] as num).toInt(),
      );

  Map<String, dynamic> toJson() => {
        'order_id': orderId,
        'status': status.toJson(),
        'driver': driver?.toJson(),
        'pickup': pickup.toJson(),
        'dropoff': dropoff.toJson(),
        'eta_minutes': etaMinutes,
        'path_tail': pathTail.map((e) => e.toJson()).toList(),
        'next_poll_seconds': nextPollSeconds,
      };
}

